// Builds supabase/functions/ai-dashboard.ts (and stripe-webhook-dashboard.ts): each function as one file, for pasting into
// Supabase's browser editor (Edge Functions → Deploy a new function → Via Editor).
// Run after changing anything in supabase/functions/ai/: node tools/bundle-ai.mjs
// (tests/ai.test.mjs fails while the generated file is out of date.)
import fs from "node:fs";

const dir = new URL("../supabase/functions/ai/", import.meta.url);
// Dependencies first, so everything is defined before index.ts runs.
export const FILES = ["teachback.ts", "librarian.ts", "study.ts", "pathways.ts", "video.ts", "talk.ts", "scenario.ts", "deeper.ts", "organize.ts", "challenge.ts", "path.ts", "weekly-rules.ts", "weekly-first.ts", "weekly.ts", "billing.ts", "sync.ts", "homeschool.ts", "handler.ts", "index.ts"];
const localImport = /^import (type )?\{[^}]*\} from "\.\.?\/[a-z/-]+\.ts";\n/gm;

export const OUT = new URL("../supabase/functions/ai-dashboard.ts", import.meta.url);
// The Stripe webhook as one file too, for a function named "stripe-webhook".
export const OUT_WEBHOOK = new URL("../supabase/functions/stripe-webhook-dashboard.ts", import.meta.url);

export function build(files = FILES, name = "ai") {
  const npmImports = new Set();
  const parts = files.map(f => {
    const src = fs.readFileSync(new URL(f, dir), "utf8").replace(localImport, "");
    const body = src.split("\n").filter(line => {
      if (line.startsWith("import ")) { npmImports.add(line); return false; }
      return true;
    }).join("\n");
    return `// ---------- ${f} ----------\n${body.trim()}\n`;
  });
  return `// GENERATED by tools/bundle-ai.mjs from supabase/functions/ai/*.ts. Don't edit by hand.
// Paste this whole file into Supabase's function editor for a function named "${name}".
${[...npmImports].join("\n")}

${parts.join("\n")}`;
}

// The Weekly Challenge's rules are written once, for the extension (content/weekly-shared.js), and
// copied here so the server checks stories exactly the same way.
export const RULES = new URL("../supabase/functions/ai/weekly-rules.ts", import.meta.url);
export function buildRules() {
  const js = fs.readFileSync(new URL("../content/weekly-shared.js", import.meta.url), "utf8");
  return `// GENERATED by tools/bundle-ai.mjs from content/weekly-shared.js. Don't edit by hand.\n// deno-lint-ignore-file\n${js.trim()}\n\nexport { wkStart, wkTidy, wkWeekOf, wkEnding, wkCalculate, wkChoose, wkAllocate };\n`;
}

// The first Weekly Challenge story (weekly-sample.json), built in: everyone gets it until an editor
// publishes one, so the box is never empty.
export const FIRST = new URL("../supabase/functions/ai/weekly-first.ts", import.meta.url);
export function buildFirst() {
  const story = JSON.parse(fs.readFileSync(new URL("../weekly-sample.json", import.meta.url), "utf8"));
  return `// GENERATED by tools/bundle-ai.mjs from weekly-sample.json. Don't edit by hand.\n// The first Weekly Challenge, built in: what everyone gets until an editor publishes a story.\nexport const WEEKLY_FIRST: Record<string, unknown> = ${JSON.stringify(story)};\n`;
}

export const buildWebhook = () => build(["billing.ts", "../stripe-webhook/index.ts"], "stripe-webhook");

if (import.meta.url === `file://${process.argv[1]}`) {
  fs.writeFileSync(RULES, buildRules());
  fs.writeFileSync(FIRST, buildFirst());
  fs.writeFileSync(OUT, build());
  fs.writeFileSync(OUT_WEBHOOK, buildWebhook());
  console.log("wrote supabase/functions/ai-dashboard.ts and stripe-webhook-dashboard.ts");
}
